/* The tables of M15 · Homework and diary. */

export const homework = defineTable(
  'homework',
  { module: 'M15', scope: 'branch', member: { read: { status: ['published', 'closed'] } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionSubjectId: uuid()
      .references((): AnyPgColumn => sectionSubjects.id)
      .notNull(),
    /** copied for filtering */
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    assignedBy: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    title: text().notNull(),
    /** rich text */
    instructions: text(),
    assignedOn: dateStr().notNull(),
    dueDate: dateStr().notNull(),
    submission: enumText(homeworkSubmissionModes).notNull().default('in_notebook'),
    maxMarks: decimal(6, 2),
    unitId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    /** scheduled publishing */
    publishAt: timestamptz(),
    allowLate: boolean().notNull().default(true),
    status: enumText(homeworkStatuses).notNull().default('draft'),
  },
  (t) => [
    check('homework_due_date_from', sql`${t.dueDate} >= ${t.assignedOn}`),
    positive('homework', t.maxMarks),
    index('homework_section_due_date_idx').on(t.orgId, t.sectionId, t.dueDate),
    index('homework_assigned_by_assigned_on_idx').on(t.orgId, t.assignedBy, t.assignedOn),
  ],
);

export const homeworkSubmissions = defineTable(
  'homework_submissions',
  {
    module: 'M15',
    scope: 'branch',
    family: 'studentId',
    familyRule: {
      read: true,
      insert: { status: ['pending', 'submitted', 'late'] },
      update: { status: ['pending', 'submitted', 'late', 'returned'] },
    },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    homeworkId: uuid()
      .references((): AnyPgColumn => homework.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    status: enumText(homeworkSubmissionStatuses).notNull().default('pending'),
    answerText: text(),
    submittedAt: timestamptz(),
    checkedBy: uuid().references((): AnyPgColumn => profiles.id),
    checkedAt: timestamptz(),
    /** ≤ the homework's `max_marks` */
    marks: decimal(6, 2),
    remark: text(),
  },
  (t) => [
    nonNegative('homework_submissions', t.marks),
    uniqueIndex('homework_submissions_homework_student_uq')
      .on(t.homeworkId, t.studentId)
      .where(live(t)),
  ],
);

/** What happened in class today, per subject, plus a general note from the class teacher. */
export const diaryEntries = defineTable(
  'diary_entries',
  { module: 'M15', scope: 'branch', member: { read: { status: 'published' } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    entryDate: dateStr().notNull(),
    /** empty for the class teacher's general note */
    sectionSubjectId: uuid().references((): AnyPgColumn => sectionSubjects.id),
    /** rich text */
    body: text().notNull(),
    postedBy: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    status: enumText(diaryEntryStatuses).notNull().default('draft'),
    publishedAt: timestamptz(),
  },
  (t) => [
    uniqueIndex('diary_entries_section_entry_date_section_subject_uq')
      .on(
        t.sectionId,
        t.entryDate,
        sql`coalesce(${t.sectionSubjectId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

export const diaryAcknowledgements = defineTable(
  'diary_acknowledgements',
  { module: 'M15', scope: 'branch', family: 'studentId', familyRule: 'append' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    entryDate: dateStr().notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    /** the guardian */
    acknowledgedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    acknowledgedAt: timestamptz().notNull(),
  },
  (t) => [
    uniqueIndex('diary_acknowledgements_student_entry_date_uq')
      .on(t.studentId, t.entryDate)
      .where(live(t)),
  ],
);
